-- 세트 509. 여러 번 실행해도 안전하다 (NOT EXISTS 가드). 원본: 02_quest_set.sql, 03_quest_set509.sql, 05·06·08. docs/specs/spec_pilot_gap_sets.md
INSERT INTO quest_set (id, title, description, sandbox_type, category)
SELECT 509, 'SQL 중급 (1) 함수: 문자열·숫자·날짜·NULL, CASE', 'SELECT 안에서 값을 가공하는 함수를 한 가지씩 써 봅니다. NULL 다루기(IFNULL, COALESCE), 문자열(CONCAT, SUBSTRING, REPLACE), 숫자(ROUND), 날짜(DATE_FORMAT, DATEDIFF), 조건에 따라 값 바꾸기(CASE)를 터미널과 퀴즈로 익힙니다.', 'linux-db', '데이터베이스'
FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM quest_set WHERE id = 509);
UPDATE quest_set SET display_order = 730, unit_id = (SELECT id FROM unit WHERE id = 30), icon = '🧮' WHERE id = 509;

INSERT INTO quest (quest_set_id, order_index, title, description, hint, solution, setup_cmd, grade_cmd, kind, choices, answer_index, explanation, answer_spec, template, checks, docs)
SELECT 509, 1, 'NULL 은 값이 아니다', '`members` 의 `nick`(별명) 칸은 비어 있는 사람이 있습니다. 비어 있는 칸은 **NULL**(값이 없음) 입니다. `SELECT NULL = NULL;` 의 결과는 무엇일까요?', 'NULL 은 "모른다"에 가깝습니다. 모르는 것 둘이 같은지는 알 수 없습니다.', NULL, NULL, '[]', 'choice', '["1 (참)", "NULL (참도 거짓도 아님)", "0 (거짓)", "오류가 난다"]', 1, 'NULL 이 끼어든 비교는 참(1)도 거짓(0)도 아닌 NULL 이 됩니다. 그래서 NULL 인 행을 찾을 때는 `= NULL` 이 아니라 `IS NULL` 을 씁니다. 그리고 NULL 이 섞인 계산이나 결과를 보기 좋게 바꿔 주는 함수가 다음 문제부터 나옵니다.', NULL, NULL, NULL, NULL
FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM quest WHERE quest_set_id = 509 AND order_index = 1);

INSERT INTO quest (quest_set_id, order_index, title, description, hint, solution, setup_cmd, grade_cmd, kind, choices, answer_index, explanation, answer_spec, template, checks, docs)
SELECT 509, 2, 'IFNULL: 비어 있으면 다른 값으로', '`club` 데이터베이스의 `members` 테이블에서 `nick` 이 비어(NULL) 있는 사람은 **`none`** 으로 보이게 하려 합니다. `name` 과, 별명(비어 있으면 `none`)을 조회해 **`/tmp/q2.txt`** 에 저장하세요. 열 이름 없이 값만 저장하려면 `mariadb -N` 을 쓰세요.

`IFNULL(값, 대체값)` 은 값이 NULL 이면 대체값을, 아니면 값을 그대로 돌려줍니다.', '`mariadb -N club -e "SELECT name, IFNULL(nick, ...) FROM members" > 파일` 형태입니다. 대체값 `none` 은 문자열이라 따옴표로 감쌉니다. 바깥 따옴표와 겹치지 않게 안쪽은 작은따옴표를 쓰세요.', 'mariadb -N club -e "SELECT name, IFNULL(nick,''none'') FROM members" > /tmp/q2.txt
cat /tmp/q2.txt

# IFNULL(a, b): a 가 NULL 이면 b. 화면·보고서에 NULL 대신 보여 줄 값을 정할 때 쓴다', '["sh", "-c", "nohup mysqld_safe >/dev/null 2>&1 & for i in $(seq 1 60); do mariadb -e ''select 1'' >/dev/null 2>&1 && break; sleep 0.5; done; mariadb -e ''DROP DATABASE IF EXISTS club; CREATE DATABASE club; USE club; CREATE TABLE members (id INT PRIMARY KEY, name VARCHAR(20) NOT NULL, nick VARCHAR(20), phone VARCHAR(20), email VARCHAR(40), joined DATE NOT NULL, score INT NOT NULL); INSERT INTO members VALUES (1,\\"kim\\",\\"k\\",\\"010-1111-2222\\",\\"kim@example.com\\",\\"2026-01-15\\",88),(2,\\"lee\\",NULL,NULL,\\"lee@example.com\\",\\"2026-01-28\\",92),(3,\\"park\\",\\"pk\\",\\"010-3333-4444\\",NULL,\\"2026-02-03\\",75),(4,\\"choi\\",NULL,NULL,NULL,\\"2026-02-20\\",60),(5,\\"jung\\",\\"jj\\",\\"010-5555-6666\\",\\"jung@example.com\\",\\"2026-03-05\\",95),(6,\\"han\\",NULL,\\"010-7777-8888\\",NULL,\\"2026-03-12\\",81);''; rm -f /tmp/*.txt /tmp/*.sh /tmp/*.sql /tmp/*.cnf"]', '["sh", "-c", "( [ -s /tmp/q2.txt ] ) && ( [ -s /tmp/q2.txt ] && [ \\"$(sort /tmp/q2.txt)\\" = \\"$(mariadb -N club -e \\"SELECT name, IFNULL(nick,''none'') FROM members\\" | sort)\\" ] )"]', 'terminal', NULL, NULL, NULL, NULL, NULL, '[{"label": "결과 파일이 있다", "cmd": ["sh", "-c", "[ -s /tmp/q2.txt ]"]}, {"label": "NULL 대신 none 이 나온다", "cmd": ["sh", "-c", "[ -s /tmp/q2.txt ] && [ \\"$(sort /tmp/q2.txt)\\" = \\"$(mariadb -N club -e \\"SELECT name, IFNULL(nick,''none'') FROM members\\" | sort)\\" ]"]}]', '[{"title": "MariaDB 함수", "url": "https://mariadb.com/kb/en/built-in-functions/"}, {"title": "MariaDB NULL 값", "url": "https://mariadb.com/kb/en/null-values/"}]'
FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM quest WHERE quest_set_id = 509 AND order_index = 2);

INSERT INTO quest (quest_set_id, order_index, title, description, hint, solution, setup_cmd, grade_cmd, kind, choices, answer_index, explanation, answer_spec, template, checks, docs)
SELECT 509, 3, 'COALESCE: 처음으로 값이 있는 것 고르기', '연락처가 전화번호(`phone`)일 수도, 이메일(`email`)일 수도, 둘 다 없을 수도 있습니다. **전화번호가 있으면 전화번호, 없으면 이메일, 둘 다 없으면 `none`** 을 보여 `name` 과 함께 **`/tmp/q3.txt`** 에 저장하세요 (`-N` 사용).

`COALESCE(a, b, c, ...)` 는 왼쪽부터 보다가 **처음으로 NULL 이 아닌 값**을 돌려줍니다. 인자는 몇 개든 쓸 수 있어요(IFNULL 은 2개만).', '`COALESCE(phone, email, ...)` 의 마지막 인자로 최후의 값을 두면 됩니다.', 'mariadb -N club -e "SELECT name, COALESCE(phone, email, ''none'') FROM members" > /tmp/q3.txt
cat /tmp/q3.txt

# 왼쪽부터 처음 만나는 NULL 아닌 값. 모두 NULL 이면 마지막 기본값이 나온다', '["sh", "-c", "nohup mysqld_safe >/dev/null 2>&1 & for i in $(seq 1 60); do mariadb -e ''select 1'' >/dev/null 2>&1 && break; sleep 0.5; done; mariadb -e ''DROP DATABASE IF EXISTS club; CREATE DATABASE club; USE club; CREATE TABLE members (id INT PRIMARY KEY, name VARCHAR(20) NOT NULL, nick VARCHAR(20), phone VARCHAR(20), email VARCHAR(40), joined DATE NOT NULL, score INT NOT NULL); INSERT INTO members VALUES (1,\\"kim\\",\\"k\\",\\"010-1111-2222\\",\\"kim@example.com\\",\\"2026-01-15\\",88),(2,\\"lee\\",NULL,NULL,\\"lee@example.com\\",\\"2026-01-28\\",92),(3,\\"park\\",\\"pk\\",\\"010-3333-4444\\",NULL,\\"2026-02-03\\",75),(4,\\"choi\\",NULL,NULL,NULL,\\"2026-02-20\\",60),(5,\\"jung\\",\\"jj\\",\\"010-5555-6666\\",\\"jung@example.com\\",\\"2026-03-05\\",95),(6,\\"han\\",NULL,\\"010-7777-8888\\",NULL,\\"2026-03-12\\",81);''; rm -f /tmp/*.txt /tmp/*.sh /tmp/*.sql /tmp/*.cnf"]', '["sh", "-c", "( [ -s /tmp/q3.txt ] ) && ( [ -s /tmp/q3.txt ] && [ \\"$(sort /tmp/q3.txt)\\" = \\"$(mariadb -N club -e \\"SELECT name, COALESCE(phone, email, ''none'') FROM members\\" | sort)\\" ] )"]', 'terminal', NULL, NULL, NULL, NULL, NULL, '[{"label": "결과 파일이 있다", "cmd": ["sh", "-c", "[ -s /tmp/q3.txt ]"]}, {"label": "phone → email → none 순으로 나온다", "cmd": ["sh", "-c", "[ -s /tmp/q3.txt ] && [ \\"$(sort /tmp/q3.txt)\\" = \\"$(mariadb -N club -e \\"SELECT name, COALESCE(phone, email, ''none'') FROM members\\" | sort)\\" ]"]}]', '[{"title": "MariaDB 함수", "url": "https://mariadb.com/kb/en/built-in-functions/"}, {"title": "MariaDB NULL 값", "url": "https://mariadb.com/kb/en/null-values/"}]'
FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM quest WHERE quest_set_id = 509 AND order_index = 3);

INSERT INTO quest (quest_set_id, order_index, title, description, hint, solution, setup_cmd, grade_cmd, kind, choices, answer_index, explanation, answer_spec, template, checks, docs)
SELECT 509, 4, 'CONCAT 에 NULL 이 있으면', '문자열을 이어 붙이는 `CONCAT(a, b, ...)` 가 있습니다. `park` 은 `email` 이 NULL 입니다. `SELECT CONCAT(name, " / ", email) FROM members WHERE name = "park";` 의 결과는?', '한 군데라도 NULL 이 섞이면 이어 붙인 전체가 어떻게 될지 생각해 보세요. 앞 문제에서 NULL 이 "모른다"라고 했습니다.', NULL, NULL, '[]', 'choice', '["park / (뒤쪽만 비어 있음)", "park / NULL (글자 NULL 이 붙음)", "NULL (한 칸이라도 NULL 이면 전체가 NULL)", "오류가 난다"]', 2, 'CONCAT 은 인자 중 하나라도 NULL 이면 결과가 NULL 입니다. 그래서 비어 있을 수 있는 칸은 `CONCAT(name, " / ", IFNULL(email, "none"))` 처럼 먼저 대체값으로 바꿔서 붙입니다.', NULL, NULL, NULL, NULL
FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM quest WHERE quest_set_id = 509 AND order_index = 4);

INSERT INTO quest (quest_set_id, order_index, title, description, hint, solution, setup_cmd, grade_cmd, kind, choices, answer_index, explanation, answer_spec, template, checks, docs)
SELECT 509, 5, 'SUBSTRING: 글자 일부만 꺼내기', '이름의 **첫 글자 하나**만 꺼내려 합니다. `함수(문자열, 시작위치, 길이)` 형태이고 위치는 1부터 셉니다. 빈칸에 알맞은 함수를 고르세요.', '인자가 세 개(문자열, 위치, 길이) 필요한 함수는 글자를 잘라 내는 함수입니다.', NULL, NULL, '[]', 'fill', '["SUBSTRING", "LENGTH", "REPLACE", "ROUND"]', NULL, '`SUBSTRING(문자열, 시작, 길이)` 는 시작 위치부터 길이만큼 잘라 냅니다. LENGTH 는 길이를 세고, REPLACE 는 바꿀 글자를, ROUND 는 숫자를 다룹니다. 이 모양의 인자(3개)를 받지 않아 오류가 납니다.', '[0]', 'SELECT {0}(name, 1, 1) FROM members;', NULL, NULL
FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM quest WHERE quest_set_id = 509 AND order_index = 5);

INSERT INTO quest (quest_set_id, order_index, title, description, hint, solution, setup_cmd, grade_cmd, kind, choices, answer_index, explanation, answer_spec, template, checks, docs)
SELECT 509, 6, 'REPLACE: 글자 바꾸기', '전화번호의 하이픈(`-`)을 **모두 없애** 숫자만 보이게 하려 합니다. 전화번호가 있는 사람만(`phone IS NOT NULL`) `name` 과 하이픈 없는 전화번호를 조회해 **`/tmp/q6.txt`** 에 저장하세요 (`-N` 사용). 예: `010-1111-2222` → `01011112222`

`REPLACE(문자열, 찾을글자, 바꿀글자)` 에서 바꿀 글자를 빈 문자열 `''''` 로 하면 지워집니다.', '`REPLACE(phone, ...)` 의 두 번째 인자는 찾을 글자, 세 번째는 그 자리에 넣을 글자입니다. 빈 문자열은 따옴표 두 개를 붙여 씁니다.', 'mariadb -N club -e "SELECT name, REPLACE(phone,''-'','''') FROM members WHERE phone IS NOT NULL" > /tmp/q6.txt
cat /tmp/q6.txt

# REPLACE(문자열, 찾을것, 바꿀것). 빈 문자열로 바꾸면 그 글자가 지워진다', '["sh", "-c", "nohup mysqld_safe >/dev/null 2>&1 & for i in $(seq 1 60); do mariadb -e ''select 1'' >/dev/null 2>&1 && break; sleep 0.5; done; mariadb -e ''DROP DATABASE IF EXISTS club; CREATE DATABASE club; USE club; CREATE TABLE members (id INT PRIMARY KEY, name VARCHAR(20) NOT NULL, nick VARCHAR(20), phone VARCHAR(20), email VARCHAR(40), joined DATE NOT NULL, score INT NOT NULL); INSERT INTO members VALUES (1,\\"kim\\",\\"k\\",\\"010-1111-2222\\",\\"kim@example.com\\",\\"2026-01-15\\",88),(2,\\"lee\\",NULL,NULL,\\"lee@example.com\\",\\"2026-01-28\\",92),(3,\\"park\\",\\"pk\\",\\"010-3333-4444\\",NULL,\\"2026-02-03\\",75),(4,\\"choi\\",NULL,NULL,NULL,\\"2026-02-20\\",60),(5,\\"jung\\",\\"jj\\",\\"010-5555-6666\\",\\"jung@example.com\\",\\"2026-03-05\\",95),(6,\\"han\\",NULL,\\"010-7777-8888\\",NULL,\\"2026-03-12\\",81);''; rm -f /tmp/*.txt /tmp/*.sh /tmp/*.sql /tmp/*.cnf"]', '["sh", "-c", "( [ -s /tmp/q6.txt ] ) && ( [ -s /tmp/q6.txt ] && [ \\"$(sort /tmp/q6.txt)\\" = \\"$(mariadb -N club -e \\"SELECT name, REPLACE(phone,''-'','''') FROM members WHERE phone IS NOT NULL\\" | sort)\\" ] ) && ( [ \\"$(wc -l < /tmp/q6.txt)\\" = 4 ] )"]', 'terminal', NULL, NULL, NULL, NULL, NULL, '[{"label": "결과 파일이 있다", "cmd": ["sh", "-c", "[ -s /tmp/q6.txt ]"]}, {"label": "하이픈이 모두 사라졌다", "cmd": ["sh", "-c", "[ -s /tmp/q6.txt ] && [ \\"$(sort /tmp/q6.txt)\\" = \\"$(mariadb -N club -e \\"SELECT name, REPLACE(phone,''-'','''') FROM members WHERE phone IS NOT NULL\\" | sort)\\" ]"]}, {"label": "4명만 나온다", "cmd": ["sh", "-c", "[ \\"$(wc -l < /tmp/q6.txt)\\" = 4 ]"]}]', '[{"title": "MariaDB 함수", "url": "https://mariadb.com/kb/en/built-in-functions/"}, {"title": "MariaDB NULL 값", "url": "https://mariadb.com/kb/en/null-values/"}]'
FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM quest WHERE quest_set_id = 509 AND order_index = 6);

INSERT INTO quest (quest_set_id, order_index, title, description, hint, solution, setup_cmd, grade_cmd, kind, choices, answer_index, explanation, answer_spec, template, checks, docs)
SELECT 509, 7, 'ROUND 로 자리수 맞추기', '숫자를 반올림하는 `ROUND(숫자, 자리수)` 가 있습니다. 자리수는 **소수점 아래 몇 자리까지 남길지**입니다. `SELECT ROUND(7.456, 1);` 의 결과는?', '소수점 아래 1자리까지 남기려면 둘째 자리(5)에서 반올림합니다.', NULL, NULL, '[]', 'choice', '["7.4", "7", "7.46", "7.5"]', 3, '`ROUND(7.456, 1)` 은 소수 첫째 자리까지 남기고 둘째 자리 5 에서 반올림해 7.5 가 됩니다. 소수 둘째 자리까지면 7.46, 자리수를 0 으로 하면 7 입니다.', NULL, NULL, NULL, NULL
FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM quest WHERE quest_set_id = 509 AND order_index = 7);

INSERT INTO quest (quest_set_id, order_index, title, description, hint, solution, setup_cmd, grade_cmd, kind, choices, answer_index, explanation, answer_spec, template, checks, docs)
SELECT 509, 8, 'ROUND 와 AVG 함께 쓰기', '`members` 전원의 평균 점수(`score`)를 **소수점 아래 1자리까지 반올림**해서 **`/tmp/q8.txt`** 에 저장하세요 (값만, `-N`). 집계 함수 AVG 의 결과를 ROUND 로 한 번 더 감쌉니다.', '함수 안에 함수를 넣을 수 있습니다. 안쪽에서 평균을 구하고, 바깥에서 소수점 아래 자리수를 맞춥니다.', 'mariadb -N club -e ''SELECT ROUND(AVG(score), 1) FROM members'' > /tmp/q8.txt
cat /tmp/q8.txt

# 함수는 겹쳐 쓸 수 있다. 안쪽(AVG)이 먼저 계산되고 그 결과를 바깥(ROUND)이 받는다', '["sh", "-c", "nohup mysqld_safe >/dev/null 2>&1 & for i in $(seq 1 60); do mariadb -e ''select 1'' >/dev/null 2>&1 && break; sleep 0.5; done; mariadb -e ''DROP DATABASE IF EXISTS club; CREATE DATABASE club; USE club; CREATE TABLE members (id INT PRIMARY KEY, name VARCHAR(20) NOT NULL, nick VARCHAR(20), phone VARCHAR(20), email VARCHAR(40), joined DATE NOT NULL, score INT NOT NULL); INSERT INTO members VALUES (1,\\"kim\\",\\"k\\",\\"010-1111-2222\\",\\"kim@example.com\\",\\"2026-01-15\\",88),(2,\\"lee\\",NULL,NULL,\\"lee@example.com\\",\\"2026-01-28\\",92),(3,\\"park\\",\\"pk\\",\\"010-3333-4444\\",NULL,\\"2026-02-03\\",75),(4,\\"choi\\",NULL,NULL,NULL,\\"2026-02-20\\",60),(5,\\"jung\\",\\"jj\\",\\"010-5555-6666\\",\\"jung@example.com\\",\\"2026-03-05\\",95),(6,\\"han\\",NULL,\\"010-7777-8888\\",NULL,\\"2026-03-12\\",81);''; rm -f /tmp/*.txt /tmp/*.sh /tmp/*.sql /tmp/*.cnf"]', '["sh", "-c", "( [ -s /tmp/q8.txt ] ) && ( [ \\"$(cat /tmp/q8.txt)\\" = 81.8 ] )"]', 'terminal', NULL, NULL, NULL, NULL, NULL, '[{"label": "결과 파일이 있다", "cmd": ["sh", "-c", "[ -s /tmp/q8.txt ]"]}, {"label": "평균이 81.8 이다", "cmd": ["sh", "-c", "[ \\"$(cat /tmp/q8.txt)\\" = 81.8 ]"]}]', '[{"title": "MariaDB 함수", "url": "https://mariadb.com/kb/en/built-in-functions/"}, {"title": "MariaDB NULL 값", "url": "https://mariadb.com/kb/en/null-values/"}]'
FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM quest WHERE quest_set_id = 509 AND order_index = 8);

INSERT INTO quest (quest_set_id, order_index, title, description, hint, solution, setup_cmd, grade_cmd, kind, choices, answer_index, explanation, answer_spec, template, checks, docs)
SELECT 509, 9, 'DATE_FORMAT: 날짜를 원하는 모양으로', '가입일(`joined`)은 `2026-01-15` 처럼 저장돼 있습니다. **연-월**(`2026-01`) 모양으로만 보고 싶습니다. `name` 과 가입 연-월을 조회해 **`/tmp/q9.txt`** 에 저장하세요 (`-N`).

`DATE_FORMAT(날짜, ''형식'')` 에서 `%Y` 는 4자리 연도, `%m` 은 2자리 월, `%d` 는 2자리 일입니다.', '형식은 따옴표로 감쌉니다. 연도, 구분자 `-`, 월 순서로 이어 쓰세요. 사이의 `-` 는 그대로 출력되는 글자입니다.', 'mariadb -N club -e "SELECT name, DATE_FORMAT(joined,''%Y-%m'') FROM members" > /tmp/q9.txt
cat /tmp/q9.txt

# 월별로 묶어 세려면 이 값으로 GROUP BY 하면 된다 (월별 가입자 수 등)', '["sh", "-c", "nohup mysqld_safe >/dev/null 2>&1 & for i in $(seq 1 60); do mariadb -e ''select 1'' >/dev/null 2>&1 && break; sleep 0.5; done; mariadb -e ''DROP DATABASE IF EXISTS club; CREATE DATABASE club; USE club; CREATE TABLE members (id INT PRIMARY KEY, name VARCHAR(20) NOT NULL, nick VARCHAR(20), phone VARCHAR(20), email VARCHAR(40), joined DATE NOT NULL, score INT NOT NULL); INSERT INTO members VALUES (1,\\"kim\\",\\"k\\",\\"010-1111-2222\\",\\"kim@example.com\\",\\"2026-01-15\\",88),(2,\\"lee\\",NULL,NULL,\\"lee@example.com\\",\\"2026-01-28\\",92),(3,\\"park\\",\\"pk\\",\\"010-3333-4444\\",NULL,\\"2026-02-03\\",75),(4,\\"choi\\",NULL,NULL,NULL,\\"2026-02-20\\",60),(5,\\"jung\\",\\"jj\\",\\"010-5555-6666\\",\\"jung@example.com\\",\\"2026-03-05\\",95),(6,\\"han\\",NULL,\\"010-7777-8888\\",NULL,\\"2026-03-12\\",81);''; rm -f /tmp/*.txt /tmp/*.sh /tmp/*.sql /tmp/*.cnf"]', '["sh", "-c", "( [ -s /tmp/q9.txt ] ) && ( [ -s /tmp/q9.txt ] && [ \\"$(sort /tmp/q9.txt)\\" = \\"$(mariadb -N club -e \\"SELECT name, DATE_FORMAT(joined,''%Y-%m'') FROM members\\" | sort)\\" ] )"]', 'terminal', NULL, NULL, NULL, NULL, NULL, '[{"label": "결과 파일이 있다", "cmd": ["sh", "-c", "[ -s /tmp/q9.txt ]"]}, {"label": "연-월 모양으로 나온다", "cmd": ["sh", "-c", "[ -s /tmp/q9.txt ] && [ \\"$(sort /tmp/q9.txt)\\" = \\"$(mariadb -N club -e \\"SELECT name, DATE_FORMAT(joined,''%Y-%m'') FROM members\\" | sort)\\" ]"]}]', '[{"title": "MariaDB 함수", "url": "https://mariadb.com/kb/en/built-in-functions/"}, {"title": "MariaDB NULL 값", "url": "https://mariadb.com/kb/en/null-values/"}]'
FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM quest WHERE quest_set_id = 509 AND order_index = 9);

INSERT INTO quest (quest_set_id, order_index, title, description, hint, solution, setup_cmd, grade_cmd, kind, choices, answer_index, explanation, answer_spec, template, checks, docs)
SELECT 509, 10, 'DATEDIFF: 날짜 사이의 일수', '`DATEDIFF(나중날짜, 이전날짜)` 는 두 날짜 사이의 **일수**를 돌려줍니다. `SELECT DATEDIFF("2026-03-10", "2026-03-01");` 의 결과는?', '앞쪽(나중 날짜)에서 뒤쪽(이전 날짜)을 뺀다고 생각하세요. 3월 1일과 10일의 차이입니다.', NULL, NULL, '[]', 'choice', '["9", "10", "-9", "2026"]', 0, '3월 10일에서 3월 1일을 빼면 9일입니다. 순서를 바꿔 `DATEDIFF("2026-03-01", "2026-03-10")` 으로 쓰면 -9 가 됩니다. 오늘을 기준으로 할 때는 `DATEDIFF(CURDATE(), 가입일)` 로 "가입한 지 며칠"을 구합니다.', NULL, NULL, NULL, NULL
FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM quest WHERE quest_set_id = 509 AND order_index = 10);

INSERT INTO quest (quest_set_id, order_index, title, description, hint, solution, setup_cmd, grade_cmd, kind, choices, answer_index, explanation, answer_spec, template, checks, docs)
SELECT 509, 11, 'CASE 문 쓰는 순서', '점수에 따라 등급을 매기는 `CASE` 식입니다. **90점 이상 A, 80점 이상 B, 나머지 C** 가 되도록 카드를 알맞은 순서로 놓으세요. CASE 는 **위에서부터 차례로** 조건을 보고 처음 맞는 것을 고릅니다.', 'CASE 로 시작해 END 로 끝납니다. 위에서부터 처음 맞는 조건을 고르니, 두 WHEN 의 순서가 바뀌면 95점의 등급이 어떻게 되는지 생각해 보세요.', NULL, NULL, '[]', 'order', '["WHEN score >= 80 THEN ''B''", "END", "CASE", "ELSE ''C''", "WHEN score >= 90 THEN ''A''"]', NULL, 'CASE 로 시작해 WHEN ... THEN ... 을 위에서부터 놓고, 어느 조건에도 안 맞을 때의 ELSE 를 쓴 뒤 END 로 끝냅니다. 80 이상을 먼저 두면 95점도 B 가 되므로 높은 기준이 먼저입니다. ELSE 를 빼면 아무 조건에도 안 맞은 행은 NULL 이 됩니다.', '[2, 4, 0, 3, 1]', NULL, NULL, NULL
FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM quest WHERE quest_set_id = 509 AND order_index = 11);

INSERT INTO quest (quest_set_id, order_index, title, description, hint, solution, setup_cmd, grade_cmd, kind, choices, answer_index, explanation, answer_spec, template, checks, docs)
SELECT 509, 12, 'CASE: 조건에 따라 값 바꿔 보여 주기', '`name` 과 점수 등급 `grade` 를 조회해 **`/tmp/q12.txt`** 에 저장하세요 (`-N`). 등급은 `score` 가 **90 이상 `A`**, **80 이상 `B`**, 나머지는 `C` 입니다.', '`CASE WHEN 조건 THEN 값 WHEN 조건 THEN 값 ELSE 값 END` 를 SELECT 목록에 열 하나처럼 넣습니다. 높은 기준부터 씁니다.', 'mariadb -N club -e "SELECT name, CASE WHEN score >= 90 THEN ''A'' WHEN score >= 80 THEN ''B'' ELSE ''C'' END AS grade FROM members" > /tmp/q12.txt
cat /tmp/q12.txt

# CASE 는 값을 바꿔 보여 줄 뿐 테이블 데이터를 고치지 않는다', '["sh", "-c", "nohup mysqld_safe >/dev/null 2>&1 & for i in $(seq 1 60); do mariadb -e ''select 1'' >/dev/null 2>&1 && break; sleep 0.5; done; mariadb -e ''DROP DATABASE IF EXISTS club; CREATE DATABASE club; USE club; CREATE TABLE members (id INT PRIMARY KEY, name VARCHAR(20) NOT NULL, nick VARCHAR(20), phone VARCHAR(20), email VARCHAR(40), joined DATE NOT NULL, score INT NOT NULL); INSERT INTO members VALUES (1,\\"kim\\",\\"k\\",\\"010-1111-2222\\",\\"kim@example.com\\",\\"2026-01-15\\",88),(2,\\"lee\\",NULL,NULL,\\"lee@example.com\\",\\"2026-01-28\\",92),(3,\\"park\\",\\"pk\\",\\"010-3333-4444\\",NULL,\\"2026-02-03\\",75),(4,\\"choi\\",NULL,NULL,NULL,\\"2026-02-20\\",60),(5,\\"jung\\",\\"jj\\",\\"010-5555-6666\\",\\"jung@example.com\\",\\"2026-03-05\\",95),(6,\\"han\\",NULL,\\"010-7777-8888\\",NULL,\\"2026-03-12\\",81);''; rm -f /tmp/*.txt /tmp/*.sh /tmp/*.sql /tmp/*.cnf"]', '["sh", "-c", "( [ -s /tmp/q12.txt ] ) && ( [ -s /tmp/q12.txt ] && [ \\"$(sort /tmp/q12.txt)\\" = \\"$(mariadb -N club -e \\"SELECT name, CASE WHEN score >= 90 THEN ''A'' WHEN score >= 80 THEN ''B'' ELSE ''C'' END FROM members\\" | sort)\\" ] ) && ( [ \\"$(wc -l < /tmp/q12.txt)\\" = 6 ] )"]', 'terminal', NULL, NULL, NULL, NULL, NULL, '[{"label": "결과 파일이 있다", "cmd": ["sh", "-c", "[ -s /tmp/q12.txt ]"]}, {"label": "등급이 맞다", "cmd": ["sh", "-c", "[ -s /tmp/q12.txt ] && [ \\"$(sort /tmp/q12.txt)\\" = \\"$(mariadb -N club -e \\"SELECT name, CASE WHEN score >= 90 THEN ''A'' WHEN score >= 80 THEN ''B'' ELSE ''C'' END FROM members\\" | sort)\\" ]"]}, {"label": "6명이 나온다", "cmd": ["sh", "-c", "[ \\"$(wc -l < /tmp/q12.txt)\\" = 6 ]"]}]', '[{"title": "MariaDB 함수", "url": "https://mariadb.com/kb/en/built-in-functions/"}, {"title": "MariaDB NULL 값", "url": "https://mariadb.com/kb/en/null-values/"}]'
FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM quest WHERE quest_set_id = 509 AND order_index = 12);
